drop extension if exists "pg_net";


  create table "public"."approval_comments" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "document_supervisor_id" uuid not null default gen_random_uuid(),
    "comment" text,
    "created_by" uuid not null default gen_random_uuid(),
    "status" character varying not null
      );


alter table "public"."approval_comments" enable row level security;


  create table "public"."categories" (
    "id" uuid not null default gen_random_uuid(),
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone default now(),
    "name" character varying not null,
    "color" character varying not null,
    "user_id" uuid not null
      );


alter table "public"."categories" enable row level security;


  create table "public"."document_supervisors" (
    "id" uuid not null default gen_random_uuid(),
    "file_id" uuid not null default gen_random_uuid(),
    "supervisor_id" uuid not null default gen_random_uuid(),
    "status" character varying not null,
    "invited_by" uuid not null default gen_random_uuid(),
    "invited_at" timestamp with time zone not null,
    "responded_at" timestamp with time zone
      );


alter table "public"."document_supervisors" enable row level security;


  create table "public"."file_permissions" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "is_active" boolean not null default false,
    "permission_type" character varying not null,
    "granted_by" uuid not null default gen_random_uuid(),
    "file_id" uuid not null default gen_random_uuid(),
    "granted_to" uuid not null default gen_random_uuid()
      );


alter table "public"."file_permissions" enable row level security;


  create table "public"."file_revisions" (
    "id" uuid not null default gen_random_uuid(),
    "created_at" timestamp with time zone not null default now(),
    "file_id" uuid not null default gen_random_uuid(),
    "version_number" bigint not null,
    "storage_key" character varying not null,
    "file_hash" character varying not null,
    "size" double precision not null,
    "uploaded_at" timestamp with time zone
      );


alter table "public"."file_revisions" enable row level security;


  create table "public"."files" (
    "id" uuid not null default gen_random_uuid(),
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone,
    "user_id" uuid not null default gen_random_uuid(),
    "folder_id" uuid not null default gen_random_uuid(),
    "name" character varying not null,
    "created_by" character varying not null,
    "updated_by" character varying,
    "extension" character varying not null,
    "size" double precision not null default '0'::double precision,
    "path" character varying not null,
    "is_favourite" boolean not null default false,
    "is_deleted" boolean not null default false,
    "category_id" uuid
      );


alter table "public"."files" enable row level security;


  create table "public"."folder_permissions" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "folder_id" uuid not null default gen_random_uuid(),
    "granted_to" uuid not null default gen_random_uuid(),
    "granted_by" uuid not null default gen_random_uuid(),
    "permission_type" character varying not null,
    "is_active" boolean not null default true
      );


alter table "public"."folder_permissions" enable row level security;


  create table "public"."folders" (
    "id" uuid not null default gen_random_uuid(),
    "user_id" uuid not null default gen_random_uuid(),
    "name" character varying not null default ''::character varying,
    "created_at" timestamp with time zone not null default now(),
    "updated_at" timestamp with time zone,
    "created_by" character varying not null,
    "updated_by" character varying,
    "path" character varying not null,
    "is_favourite" boolean not null default false,
    "parent_id" uuid,
    "is_deleted" boolean not null default false
      );


alter table "public"."folders" enable row level security;


  create table "public"."profiles" (
    "id" uuid not null,
    "username" character varying not null default ''::character varying,
    "is_active" boolean not null default true,
    "deleted_at" timestamp with time zone,
    "home_folder_id" uuid not null
      );


alter table "public"."profiles" enable row level security;


  create table "public"."word_collaboration_documents" (
    "id" uuid not null default gen_random_uuid(),
    "file_id" uuid not null,
    "state" jsonb not null,
    "version_number" integer not null default 1,
    "updated_at" timestamp with time zone not null default now(),
    "updated_by" uuid
      );


alter table "public"."word_collaboration_documents" enable row level security;


  create table "public"."word_collaboration_events" (
    "id" uuid not null default gen_random_uuid(),
    "file_id" uuid not null,
    "created_by" uuid not null,
    "event_type" character varying not null,
    "payload" jsonb not null,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."word_collaboration_events" enable row level security;


  create table "public"."word_collaboration_sessions" (
    "id" uuid not null default gen_random_uuid(),
    "file_id" uuid not null,
    "user_id" uuid not null,
    "connection_id" character varying not null,
    "cursor_state" jsonb,
    "selection_state" jsonb,
    "is_active" boolean not null default true,
    "last_seen_at" timestamp with time zone not null default now(),
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."word_collaboration_sessions" enable row level security;

