  create policy "Enable users to view their own data only"
  on "public"."categories"
  as permissive
  for select
  to authenticated
using ((( SELECT auth.uid() AS uid) = user_id));



  create policy "Give users access"
  on "public"."document_supervisors"
  as permissive
  for select
  to public
using ((supervisor_id = auth.uid()));



  create policy "Owner and grantee manages file permissions"
  on "public"."file_permissions"
  as permissive
  for select
  to public
using (((granted_to = auth.uid()) OR (granted_by = auth.uid())));



  create policy "Enable insert for users based on user_id"
  on "public"."files"
  as permissive
  for insert
  to public
with check ((( SELECT auth.uid() AS uid) = user_id));



  create policy "Enable users to update their own data"
  on "public"."files"
  as permissive
  for update
  to authenticated
using ((auth.uid() = user_id))
with check ((auth.uid() = user_id));



  create policy "Enable users to view their own data only"
  on "public"."files"
  as permissive
  for select
  to authenticated
using ((( SELECT auth.uid() AS uid) = user_id));



  create policy "files insert owner or folder write"
  on "public"."files"
  as permissive
  for update
  to public
using ((EXISTS ( SELECT 1
   FROM public.folder_permissions fperm
  WHERE ((fperm.folder_id = files.folder_id) AND (fperm.granted_to = auth.uid()) AND (fperm.is_active = true) AND ((fperm.permission_type)::text = 'write'::text)))));



  create policy "files select own or shared read write"
  on "public"."files"
  as permissive
  for select
  to public
using ((EXISTS ( SELECT 1
   FROM public.file_permissions fp
  WHERE ((fp.file_id = files.id) AND (fp.granted_to = auth.uid()) AND (fp.is_active = true) AND ((fp.permission_type)::text = ANY ((ARRAY['read'::character varying, 'write'::character varying])::text[]))))));



  create policy "Grantee sees own folder permissions"
  on "public"."folder_permissions"
  as permissive
  for select
  to public
using ((granted_to = auth.uid()));



  create policy "Owner manages folder permissions"
  on "public"."folder_permissions"
  as permissive
  for select
  to public
using ((EXISTS ( SELECT 1
   FROM public.folders
  WHERE ((folders.id = folder_permissions.folder_id) AND (folders.user_id = auth.uid())))));



  create policy "Enable insert for users based on user_id"
  on "public"."folders"
  as permissive
  for insert
  to public
with check ((( SELECT auth.uid() AS uid) = user_id));



  create policy "Enable users to update their own data"
