  create policy "Enable users to insert documents 1cqvdzs_0"
  on "storage"."objects"
  as permissive
  for insert
  to public
with check (((bucket_id = 'Documents'::text) AND (((auth.uid())::text = (storage.foldername(name))[1]) OR (EXISTS ( SELECT 1
   FROM public.document_supervisors ds
  WHERE ((ds.supervisor_id = auth.uid()) AND ((ds.status)::text = 'accepted'::text) AND (POSITION(((ds.file_id)::text) IN (objects.name)) > 0)))))));



