  create policy "Give users access to own folder 1cqvdzs_3"
  on "storage"."objects"
  as permissive
  for delete
  to public
using (((bucket_id = 'Documents'::text) AND (( SELECT (auth.uid())::text AS uid) = (storage.foldername(name))[1])));



